<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/geop_v8.php';
require_role(['TI','GESTOR','GESTOR_SINDICO']);check_csrf();geop_v8_boot($pdo);
if (!geop_v8_feature_ready($pdo)) {
    if ((current_user()['perfil'] ?? '') === 'TI') redirect('atualizar_geop_v8');
    http_response_code(503); die('O módulo GEOP V8 aguarda a atualização do banco pelo TI.');
}$u=current_user();$uid=(int)$u['id'];$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$action=$_POST['action']??'';
  if($action==='modelo'){$cat=(int)$_POST['categoria_id'];$nome=trim((string)$_POST['nome']);if($cat<=0||$nome==='')throw new RuntimeException('Categoria e nome são obrigatórios.');$pdo->prepare("INSERT INTO checklist_modelos(categoria_id,nome,criado_por) VALUES(?,?,?)")->execute([$cat,$nome,$uid]);$msg='Modelo criado.';}
  elseif($action==='item'){$mid=(int)$_POST['modelo_id'];$desc=trim((string)$_POST['descricao']);if($mid<=0||$desc==='')throw new RuntimeException('Modelo e descrição são obrigatórios.');$pdo->prepare("INSERT INTO checklist_modelo_itens(modelo_id,descricao,obrigatorio,exige_foto,ordem) VALUES(?,?,?,?,?)")->execute([$mid,$desc,!empty($_POST['obrigatorio'])?1:0,!empty($_POST['exige_foto'])?1:0,(int)($_POST['ordem']??0)]);$msg='Item adicionado.';}
  elseif($action==='toggle'){$id=(int)$_POST['id'];$pdo->prepare("UPDATE checklist_modelos SET ativo=IF(ativo=1,0,1) WHERE id=?")->execute([$id]);$msg='Status do modelo alterado.';}
 }catch(Throwable $e){$err=$e->getMessage();}
}
$cats=$pdo->query("SELECT id,nome FROM categorias WHERE ativo=1 ORDER BY nome")->fetchAll(PDO::FETCH_ASSOC);$models=$pdo->query("SELECT m.*,c.nome categoria_nome,u.nome criado_por_nome,(SELECT COUNT(*) FROM checklist_modelo_itens i WHERE i.modelo_id=m.id) itens FROM checklist_modelos m JOIN categorias c ON c.id=m.categoria_id LEFT JOIN usuarios u ON u.id=m.criado_por ORDER BY m.id DESC")->fetchAll(PDO::FETCH_ASSOC);$items=$pdo->query("SELECT i.*,m.nome modelo_nome,c.nome categoria_nome FROM checklist_modelo_itens i JOIN checklist_modelos m ON m.id=i.modelo_id JOIN categorias c ON c.id=m.categoria_id ORDER BY c.nome,m.id,i.ordem,i.id")->fetchAll(PDO::FETCH_ASSOC);render_header('Checklists por categoria');
?>
<h1 class="h3 mb-1">Checklists por categoria</h1><p class="text-muted mb-3">Cada nova OS recebe um snapshot do checklist ativo da categoria, preservando o histórico.</p><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif?><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif?>
<div class="row g-3 mb-3"><div class="col-lg-5"><div class="card h-100"><div class="card-body"><h2 class="h5">Novo modelo</h2><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="modelo"><div class="col-12"><label class="form-label">Categoria</label><select class="form-select" name="categoria_id" required><option value="">Selecione</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['nome'])?></option><?php endforeach?></select></div><div class="col-12"><label class="form-label">Nome do checklist</label><input class="form-control" name="nome" placeholder="Ex.: Checklist elétrica" required></div><div class="col-12"><button class="btn btn-primary">Criar modelo</button></div></form></div></div></div><div class="col-lg-7"><div class="card h-100"><div class="card-body"><h2 class="h5">Adicionar item</h2><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="item"><div class="col-md-6"><label class="form-label">Modelo</label><select class="form-select" name="modelo_id" required><?php foreach($models as $m):?><option value="<?=(int)$m['id']?>"><?=e($m['categoria_nome'].' — '.$m['nome'])?></option><?php endforeach?></select></div><div class="col-md-6"><label class="form-label">Descrição</label><input class="form-control" name="descricao" required></div><div class="col-md-3"><label class="form-label">Ordem</label><input class="form-control" type="number" name="ordem" value="0"></div><div class="col-md-3 d-flex align-items-end"><div class="form-check"><input class="form-check-input" type="checkbox" name="obrigatorio" id="obr"><label class="form-check-label" for="obr">Obrigatório</label></div></div><div class="col-md-3 d-flex align-items-end"><div class="form-check"><input class="form-check-input" type="checkbox" name="exige_foto" id="foto"><label class="form-check-label" for="foto">Exige foto</label></div></div><div class="col-md-3 d-grid align-items-end"><button class="btn btn-primary">Adicionar item</button></div></form></div></div></div></div>
<div class="card mb-3"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Categoria</th><th>Modelo</th><th>Itens</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($models as $m):?><tr><td><?=e($m['categoria_nome'])?></td><td><?=e($m['nome'])?></td><td><?=e((string)$m['itens'])?></td><td><span class="badge <?= $m['ativo']?'text-bg-success':'text-bg-secondary'?>"><?= $m['ativo']?'Ativo':'Inativo'?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$m['id']?>"><button class="btn btn-sm btn-outline-secondary">Ativar/Inativar</button></form></td></tr><?php endforeach?></tbody></table></div></div>
<div class="card"><div class="card-body"><h2 class="h5">Itens cadastrados</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Categoria</th><th>Modelo</th><th>Item</th><th>Obrigatório</th><th>Foto</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['categoria_nome'])?></td><td><?=e($i['modelo_nome'])?></td><td><?=e($i['descricao'])?></td><td><?=!empty($i['obrigatorio'])?'Sim':'Não'?></td><td><?=!empty($i['exige_foto'])?'Sim':'Não'?></td></tr><?php endforeach?></tbody></table></div></div></div>
<?php render_footer(); ?>
